server {
    listen 80;
    server_name localhost;

    # Proxy API routes with caching
    location /api/ {
        # Cache configuration - 10m size, 1000s timeout
        proxy_cache apicache;
        proxy_cache_valid 200 1000;
        proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;

        # Proxy headers
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Forward to backend servers
        proxy_pass http://localhost:3000;
    }

    # Service1 endpoint
    location /api/service1 {
        proxy_pass http://localhost:3000/data;
        proxy_cache_valid 200 1000;
        add_header X-Cache-Status $upstream_cache_status;
    }

    # Service2 endpoint
    location /api/service2 {
        proxy_pass http://localhost:3001/data;
        proxy_cache_valid 200 1000;
        add_header X-Cache-Status $upstream_cache_status;
    }

    # Service3 endpoint
    location /api/service3 {
        proxy_pass http://localhost:3002/data;
        proxy_cache_valid 200 1000;
        add_header X-Cache-Status $upstream_cache_status;
    }

    # Service4 endpoint
    location /api/service4 {
        proxy_pass http://localhost:3003/data;
        proxy_cache_valid 200 1000;
        add_header X-Cache-Status $upstream_cache_status;
    }

    # Redirect routes with 302 status
    location /sunny {
        location: /api/service1;
        rewrite ^/sunny/(.*)$ /$1 permanent;
        add_header Location /api/service1 redirect;
        add_header X-Cache-Status $upstream_cache_status;
    }

    location /woods {
        location: /api/service2;
        rewrite ^/woods/(.*)$ /$1 permanent;
        add_header Location /api/service2 redirect;
        add_header X-Cache-Status $upstream_cache_status;
    }

    location /stream {
        location: /api/service3;
        rewrite ^/stream/(.*)$ /$1 permanent;
        add_header Location /api/service3 redirect;
        add_header X-Cache-Status $upstream_cache_status;
    }
}
EOF
